import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"易附錄纂注卷十四","description":"易附錄纂注 - 易附錄纂注卷十四","frontmatter":{"title":"易附錄纂注卷十四","description":"易附錄纂注 - 易附錄纂注卷十四"},"headers":[],"relativePath":"classics/yifulu-zuanzhu/015.md","filePath":"classics/yifulu-zuanzhu/015.md"}'),r={name:"classics/yifulu-zuanzhu/015.md"};function i(c,a,o,u,d,p){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附錄纂注卷十四",tabindex:"-1"},[n("易附錄纂注卷十四 "),e("a",{class:"header-anchor",href:"#易附錄纂注卷十四","aria-label":"Permalink to “易附錄纂注卷十四”"},"​")],-1),e("p",null,"欽定四庫全書",-1),e("p",null,"元胡一桂撰",-1),e("p",null,"擇地潔處為蓍室，南戶，置床於室中央。 床大約長五尺，廣三尺，毋太近壁。 蓍五十莖，韜以纁帛，貯以皂囊，納之櫝中，置於床北。 櫝以竹筒，或堅木，或布漆為之，圓徑三寸，如蓍之長，半為底，半為蓋，下別為臺，函之使不偃仆。 附錄。 蒿固非蓍，然亦猶是其類。若以木棋行算金錢當之，則其去蓍益遠矣。答曾三異。 設木格於櫝南，居床二分之北。 格以橫木板為之，高一尺，長竟床。當中為兩大刻，相距一尺。大刻之西為三小刻，相距各五寸許。下施橫足，側立案上。 置香爐一于格南，香合一於爐南。日炷香致敬。將筮，則灑掃拂拭，滌硯一、注水及筆一、墨一、黃漆板一於爐東，東上。筮者齊潔衣冠，北面盥手焚香致敬。 筮者北面，見儀禮。若使人筮，則主人焚香畢，少退，北面立。筮者進，立於床前，少西，南向受命。主人直述所佔之事，筮者許諾。主人右還，西向立，筮者右還北向立。 兩手奉櫝蓋置於格南爐北，出蓍於櫝，去囊解韜，置於櫝東，合五十策，兩手執之，燻於爐上， 此後所用蓍策之數，其說並見啟蒙。 命之曰：「假爾泰筮有常，假爾泰筮有常，某官姓名，今以某事云云，未知可否。爰質所疑，於神於靈。吉凶得失，悔吝憂虞，惟爾有神，尚明告之。」乃以右手取其一策反於櫝中，而以左右手中分四十九策置格之左右兩大刻， 此第一營所謂「分而為二以象兩」者也。 次以左手取左大刻之策執之，而以右手取右大刻之一策掛於左手之小指間， 此第二營所謂「掛一以象三」者也。 次以右手四揲左手之策， 此第三營之半，所謂「揲之以四以象四時」者也。 次歸其所餘之策，或一、或二、或三、或四，而扐之左手無名指間， 此第四營之半，所謂「歸奇於扐以象閏」者也。 次以右手反過揲之策於左大刻，遂取右大刻之策執之，而以左手四揲之。 此第三營之半。 次歸其所餘之策如前，而扐之左手中指之間。 此第四營之半，所謂「再扐以象再閏」者也。一變所餘之策，左一則右必三，左二則右亦二，左三則右必一，左四則右亦四。通掛一之策，不五則九，五以一其四而為奇，九以兩其四而為偶，奇者三而偶者一也。 次以右手反過揲之策於右大刻，而合左手一掛二扐之策，置於格上第一小刻， 以東為上，後放此。 是為一變。再以兩手取左右大刻之蓍合之， 或四十四策，或四十策。 復四營如第一變之儀，而置其掛扐之策于格上第二小刻，是為二變。 二變所餘之策，左一則右必二，左二則右必一，左三則右必四，左四則右必三。通掛一之策，不四則八，四以一其四而為奇，八以兩其四而為偶，奇偶各得四之二焉。 又再取左右大刻之蓍合之， 或四十策，或三十六策，或三十二策。 履四營如第二變之儀，而置其掛扐之策于格上，第三小刻，是為三變。 三變餘策，與二變同。 三變既畢，乃視其三變所得掛扐過揲之策，而畫其爻於版。 掛扐之數，五、四為奇，九、八為偶。掛扐三奇合十三策，則過揲三十六策，而為老陽，其畫為口，所謂「重」也。掛扐兩奇一偶合十七策，則過揲三十二策而為少陰，其畫為一，所謂「拆」也。掛扐兩偶一奇合二十一策，則過揲二十八策而為少陽，其畫為一，所謂「單」也。掛扐三偶合二十五策，則過揲二十四策而為老陰，其畫為乂，所謂「交」也。 附錄：交者，拆之聚，故為老陰；重者，單之積，故為老陽。 如是每三變而成爻。 第一、第四、第七、第十、第十三、第十六，凡六變並同。但第三變以下不命，而但用四十九蓍耳。第二、第五、第八、第十一、第十四、第十七，凡六變亦同。第三、第六、第九、第十二、第十五、第十八，凡六變亦同。 凡十有八變而成卦，乃考其卦之變，而佔其事之吉凶。 卦變別有圖，說見啟蒙。 禮畢，韜蓍，襲之以囊，入櫝加蓋，斂筆研墨版，再焚香致敬而退。 如使人筮，則主人焚香揖筮者而退。 易附錄纂注卷十四",-1)])])}const _=t(r,[["render",i]]);export{m as __pageData,_ as default};
